'use strict';

// Built-in fallback animations for the avatar (power-up) effects. Each clip is a
// small animated GIF embedded as a data URL so the command works with no external
// hosting. Operators can override any effect with the AVEFFECT_MEDIA_<NAME>
// environment variable (a public HTTPS URL or an inline data: URL).

const DEFAULT_MEDIA = Object.freeze({
  love: '',
  angry: '',
  laugh: '',
  cry: '',
});

function normalizeName(value) {
  return String(value ?? '').trim().toLowerCase();
}

/** Returns the animation for an effect: env override first, then the built-in clip. */
function getEffectMedia(effect) {
  const name = normalizeName(effect);
  if (!name) return null;
  const override = process.env[`AVEFFECT_MEDIA_${name.toUpperCase()}`];
  if (override && String(override).trim()) return String(override).trim();
  const fallback = DEFAULT_MEDIA[name] || process.env.AVEFFECT_MEDIA_DEFAULT;
  if (!fallback) return null;
  return `data:image/gif;base64,${fallback}`;
}

/** True when the effect has a bundled default animation. */
function hasEffectMedia(effect) {
  return Boolean(DEFAULT_MEDIA[normalizeName(effect)]);
}

module.exports = { getEffectMedia, hasEffectMedia, DEFAULT_MEDIA };
